"""Audio preprocessing before ASR: timeline stabilize, light denoise, vocal separation."""

from __future__ import annotations

import logging
import os
import shutil
import subprocess
import tempfile
from pathlib import Path
from typing import Any, Callable

from ..ffmpeg_util import resolve_ffmpeg, resolve_ffprobe

ProgressCb = Callable[[dict[str, Any]], None]
_log = logging.getLogger("transub_engine.audio")



# Fill container audio holes with silence (player-accurate timeline). Do NOT use
# first_pts=0 — mid-stream filter rebuilds can insert huge leading silence.
_AF_TIMELINE_STABLE = "aresample=async=1"


def _run_ffmpeg(cmd: list[str], *, capture_stderr: bool = False) -> str:
    run_kwargs: dict[str, Any] = {
        "capture_output": True,
        "text": True,
        "encoding": "utf-8",
        "errors": "replace",
        "check": False,
    }
    if os.name == "nt":
        run_kwargs["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    # Prefer level-tagged logs so integrity can count [error]/[fatal] lines.
    if "-loglevel" not in cmd:
        cmd = [cmd[0], "-loglevel", "level+info", *cmd[1:]]
    proc = subprocess.run(cmd, **run_kwargs)
    stderr = proc.stderr or ""
    if proc.returncode != 0 and "Invalid loglevel" in stderr and "-loglevel" in cmd:
        i = cmd.index("-loglevel")
        cmd2 = cmd[:i] + cmd[i + 2 :]
        proc = subprocess.run(cmd2, **run_kwargs)
        stderr = proc.stderr or ""
    if proc.returncode != 0:
        err = (stderr or proc.stdout or "").strip()
        raise RuntimeError(f"ffmpeg failed ({proc.returncode}): {err[:800]}")
    return stderr if capture_stderr else ""


def stabilize_media_timeline(
    media_path: str,
    *,
    out_dir: Path | None = None,
    sample_rate: int = 16000,
) -> tuple[str, str, float | None]:
    """
    Extract mono PCM while filling audio-track holes with silence.

    Returns ``(wav_path, ffmpeg_stderr, duration_sec_or_none)``.
    """
    ffmpeg = resolve_ffmpeg()
    if not ffmpeg:
        raise RuntimeError("ffmpeg not found; cannot stabilize audio timeline")
    src = Path(media_path)
    if not src.is_file():
        raise RuntimeError(f"stabilize input missing: {media_path}")
    work = Path(out_dir) if out_dir else Path(tempfile.mkdtemp(prefix="transub_stable_"))
    work.mkdir(parents=True, exist_ok=True)
    out = work / f"{src.stem}.stable-16k.wav"
    cmd = [
        ffmpeg,
        "-y",
        "-i",
        str(src),
        "-vn",
        "-af",
        _AF_TIMELINE_STABLE,
        "-ac",
        "1",
        "-ar",
        str(int(sample_rate)),
        "-c:a",
        "pcm_s16le",
        "-f",
        "wav",
        str(out),
    ]
    stderr = _run_ffmpeg(cmd, capture_stderr=True)
    if not out.is_file() or out.stat().st_size < 64:
        raise RuntimeError(f"timeline stabilize produced empty audio: {out}")
    duration: float | None = None
    try:
        from .audio_integrity import wav_duration_s

        duration = wav_duration_s(out)
    except Exception:
        duration = None
    return str(out.resolve()), stderr, duration



def stage_media_for_long_asr(media_path: str, work_dir: Path) -> str:
    """
    Pin ASR input under the long-running window work dir.

    Light-denoise WAVs live under ``transub_audio_*`` with a start-of-job mtime.
    Long Cohere/Qwen runs (1h+) can lose that path to temp cleaners while windows
    still need it. Hardlink (same volume) or copy into ``work_dir`` so the ASR
    tree owns a stable name for the whole job.
    """
    src = Path(media_path)
    if not src.is_file():
        raise RuntimeError(f"ASR 输入音频不存在或已被清理: {media_path}")
    work = Path(work_dir)
    work.mkdir(parents=True, exist_ok=True)
    suffix = src.suffix if src.suffix else ".wav"
    dest = work / f"asr_source{suffix}"
    if dest.exists():
        try:
            if dest.samefile(src):
                return str(dest)
        except OSError:
            pass
        try:
            dest.unlink()
        except OSError:
            pass
    try:
        os.link(src, dest)
    except OSError:
        shutil.copy2(src, dest)
    if not dest.is_file() or dest.stat().st_size < 64:
        raise RuntimeError(f"无法为长片 ASR 固定输入音频: {dest}")
    return str(dest)


def touch_path(path: str | Path) -> None:
    """Refresh mtime so temp cleaners are less likely to reap an in-use file."""
    p = Path(path)
    try:
        p.touch(exist_ok=True)
    except OSError:
        try:
            os.utime(p, None)
        except OSError:
            pass


def light_denoise(media_path: str, *, out_dir: Path | None = None) -> str:
    """
    Free-tier light denoise via ffmpeg filters (highpass + mild afftdn).
    Returns path to a temporary WAV; caller should delete when done.
    """
    ffmpeg = resolve_ffmpeg()
    if not ffmpeg:
        raise RuntimeError("ffmpeg not found; cannot apply light denoise")

    src = Path(media_path)
    work = Path(out_dir) if out_dir else Path(tempfile.mkdtemp(prefix="transub_denoise_"))
    work.mkdir(parents=True, exist_ok=True)
    out = work / f"{src.stem}.denoise.wav"
    # Prefer light filters; loudnorm is two-pass and too slow on long media.
    filter_candidates = [
        f"{_AF_TIMELINE_STABLE},highpass=f=80,afftdn=nr=8:nf=-25",
        f"{_AF_TIMELINE_STABLE},highpass=f=80,lowpass=f=8000,dynaudnorm",
        f"{_AF_TIMELINE_STABLE},highpass=f=80,lowpass=f=8000",
    ]
    last_err: Exception | None = None
    for af in filter_candidates:
        cmd = [
            ffmpeg,
            "-y",
            "-i",
            str(src),
            "-vn",
            "-ac",
            "1",
            "-ar",
            "16000",
            "-af",
            af,
            "-f",
            "wav",
            str(out),
        ]
        try:
            _run_ffmpeg(cmd)
            if out.is_file() and out.stat().st_size >= 44:
                return str(out.resolve())
        except Exception as err:
            last_err = err
            continue
    if last_err:
        raise last_err
    raise RuntimeError("light denoise produced empty output")


def _demucs_available() -> bool:
    try:
        import demucs  # noqa: F401

        return True
    except Exception:
        return False


def _find_demucs_vocals(out_root: Path, media_stem: str) -> Path | None:
    """Locate demucs vocals stem under typical output layouts."""
    candidates = [
        out_root / "htdemucs" / media_stem / "vocals.wav",
        out_root / media_stem / "vocals.wav",
    ]
    for path in candidates:
        if path.is_file():
            return path
    for path in out_root.rglob("vocals.wav"):
        if path.is_file():
            return path
    return None


def _resolve_demucs_device(device: str) -> tuple[str, str]:
    """
    Returns (demucs -d value, human label).
    Demucs needs GPU-enabled PyTorch in the *engine* env (CUDA / ROCm / XPU).
    """
    want = str(device or "auto").strip().lower()
    if want in ("cpu",):
        return "cpu", "CPU（用户指定）"
    try:
        import torch
        from ..device import resolve_torch_device_key

        key = resolve_torch_device_key(want, torch_mod=torch)
        if key == "cuda":
            name = ""
            try:
                name = str(torch.cuda.get_device_name(0) or "").strip()
            except Exception:
                name = ""
            label = f"GPU（{name}）" if name else "GPU（CUDA）"
            return "cuda", label
        if key == "xpu":
            name = ""
            try:
                name = str(torch.xpu.get_device_name(0) or "").strip()
            except Exception:
                name = ""
            label = f"GPU（{name}）" if name else "GPU（Intel XPU）"
            return "xpu", label
        return (
            "cpu",
            "CPU（引擎 PyTorch 无 GPU；NVIDIA 补齐 CUDA，AMD 补齐 ROCm，Intel 补齐 XPU）",
        )
    except Exception as err:
        return "cpu", f"CPU（无法加载 torch：{err}）"


def _prepare_vram_for_demucs() -> None:
    """
    Demucs runs as a CUDA subprocess that needs contiguous VRAM.
    Prior batch items may leave engine llama / ASR weights loaded — free them first.
    """
    try:
        from ..llama_server import MANAGER as _llm

        _llm.stop(reason="pre_demucs")
    except Exception as err:
        _log.debug("pre_demucs llm stop skipped: %s", err)
    try:
        from ..runtime_release import release_gpu_memory

        release_gpu_memory(reason="pre_demucs", unload_models=True)
    except Exception as err:
        _log.debug("pre_demucs release_gpu skipped: %s", err)


def _extract_demucs_root_cause(err: str) -> str:
    """Prefer the final Exception line; traceback heads are rarely actionable."""
    text = (err or "").strip()
    if not text:
        return "(no stderr)"
    lines = [ln.strip() for ln in text.replace("\r\n", "\n").split("\n") if ln.strip()]
    skip_prefixes = (
        "File \"",
        "Traceback (most recent call last)",
        "During handling of the above",
        "The above exception was the direct cause",
    )
    for ln in reversed(lines):
        if any(ln.startswith(p) for p in skip_prefixes):
            continue
        if set(ln) <= {" ", "-", "^", "~", "`"}:
            continue
        # Typical: RuntimeError: CUDA out of memory...
        if "Error:" in ln or "Exception:" in ln or ln.startswith("error:"):
            return ln[:500]
    for ln in reversed(lines):
        if any(ln.startswith(p) for p in skip_prefixes):
            continue
        if set(ln) <= {" ", "-", "^", "~", "`"}:
            continue
        return ln[:500]
    return text[-500:]


def _demucs_err_is_oom(err: str) -> bool:
    low = (err or "").lower()
    return any(
        needle in low
        for needle in (
            "out of memory",
            "cuda out of memory",
            "cudnn_status_alloc_failed",
            "failed to allocate",
            "hiperroroutofmemory",
            "cublas_status_alloc_failed",
        )
    )


def _demucs_err_worth_segment_retry(err: str) -> bool:
    """OOM or generic CUDA alloc/launch failures that often clear with shorter segments."""
    if _demucs_err_is_oom(err):
        return True
    low = (err or "").lower()
    return any(
        needle in low
        for needle in (
            "cuda error",
            "cudaexception",
            "cudnn_status",
            "cublas_status",
            "hiperror",
            "not enough memory",
            "memory access",
        )
    )


def _format_demucs_failure(returncode: int, err: str, *, segment: int | None = None) -> str:
    text = (err or "").strip()
    root = _extract_demucs_root_cause(text)
    seg_note = f"（分段 {segment}s）" if segment else ""
    if _demucs_err_is_oom(text):
        return (
            f"Demucs failed ({returncode}): GPU 显存不足{seg_note}。"
            f"已用更短分段仍失败时可关掉其他占显存程序后重试（不强制改 CPU）。"
            f"\n{root}"
        )
    return f"Demucs failed ({returncode}): {root}"


# HTDemucs pretrained checkpoints report max segment ≈ 7.8s (CLI --segment is int).
_DEMUCS_HT_SEGMENT_MAX = 7


def _pick_demucs_segment(device_key: str) -> int | None:
    """
    Pick Demucs ``--segment`` for CUDA. Must stay ≤ pretrained HTDemucs max (~7.8s).
    Prefer shorter chunks on small GPUs so the Demucs subprocess still fits beside
    the parent engine's CUDA context. Returns None to keep Demucs default.
    """
    if str(device_key or "").strip().lower() not in ("cuda", "xpu"):
        return None
    free_gb = None
    total_gb = None
    try:
        import torch

        if torch.cuda.is_available():
            free_b, total_b = torch.cuda.mem_get_info(0)
            free_gb = float(free_b) / (1024**3)
            total_gb = float(total_b) / (1024**3)
    except Exception:
        free_gb = None
        total_gb = None
    # Parent process often still holds a CUDA context after empty_cache.
    if total_gb is not None and total_gb <= 8.5:
        return 4
    if total_gb is not None and total_gb <= 12.5:
        return 6
    if free_gb is not None and free_gb < 5.0:
        return 4
    if free_gb is not None and free_gb < 8.0:
        return 6
    return _DEMUCS_HT_SEGMENT_MAX


def _clamp_demucs_segment(seg: int | None) -> int | None:
    if seg is None:
        return None
    try:
        n = int(seg)
    except (TypeError, ValueError):
        return _DEMUCS_HT_SEGMENT_MAX
    if n <= 0:
        return None
    return max(1, min(_DEMUCS_HT_SEGMENT_MAX, n))

def _run_demucs_cli(
    cmd: list[str],
    *,
    device_label: str,
    on_progress: ProgressCb | None,
    should_cancel: Callable[[], bool] | None,
    register_subprocess: Callable[[Any], None] | None,
    started: float,
) -> tuple[int, str, bool]:
    """Run one Demucs CLI invocation. Returns (returncode, combined_err, cancelled)."""
    import re
    import threading
    import time

    from ..proc_util import kill_process_tree

    run_kwargs: dict[str, Any] = {
        "stdout": subprocess.PIPE,
        "stderr": subprocess.PIPE,
        "text": True,
        "encoding": "utf-8",
        "errors": "replace",
        "env": {
            **os.environ,
            # Reduce fragmentation when parent engine already touched CUDA.
            "PYTORCH_CUDA_ALLOC_CONF": os.environ.get(
                "PYTORCH_CUDA_ALLOC_CONF",
                "expandable_segments:True",
            ),
        },
    }
    if os.name == "nt":
        run_kwargs["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0) | getattr(
            subprocess, "CREATE_NEW_PROCESS_GROUP", 0
        )
    else:
        run_kwargs["start_new_session"] = True

    proc = subprocess.Popen(cmd, **run_kwargs)
    if register_subprocess:
        try:
            register_subprocess(proc)
        except Exception:
            pass

    stderr_chunks: list[str] = []
    stdout_chunks: list[str] = []
    stop_heartbeat = threading.Event()
    cancelled = False

    def _reader(stream, bucket: list[str]) -> None:
        try:
            for line in iter(stream.readline, ""):
                if not line:
                    break
                bucket.append(line)
                text = line.strip()
                if text and on_progress:
                    m = re.search(r"(\d{1,3})\s*%", text)
                    if m:
                        pct = max(11, min(17, 11 + int(m.group(1)) * 6 // 100))
                        try:
                            on_progress(
                                {
                                    "stage": "separate",
                                    "percent": pct,
                                    "detail": f"Demucs（{device_label}）{m.group(1)}%",
                                }
                            )
                        except Exception:
                            pass
        except Exception:
            pass
        finally:
            try:
                stream.close()
            except Exception:
                pass

    t_err = threading.Thread(target=_reader, args=(proc.stderr, stderr_chunks), daemon=True)
    t_out = threading.Thread(target=_reader, args=(proc.stdout, stdout_chunks), daemon=True)
    t_err.start()
    t_out.start()

    def _heartbeat() -> None:
        tick = 0
        while not stop_heartbeat.wait(4.0):
            if proc.poll() is not None:
                break
            if should_cancel and should_cancel():
                break
            tick += 1
            elapsed = int(time.time() - started)
            mins, secs = divmod(elapsed, 60)
            pct = min(17, 11 + (tick % 7))
            detail = f"已用 {mins}分{secs:02d}秒"
            if on_progress:
                try:
                    on_progress({"stage": "separate", "percent": pct, "detail": detail})
                except Exception:
                    break

    hb = threading.Thread(target=_heartbeat, daemon=True)
    hb.start()
    try:
        while True:
            if should_cancel and should_cancel():
                cancelled = True
                kill_process_tree(proc, reason="demucs_cancel")
                break
            if proc.poll() is not None:
                break
            time.sleep(0.4)
        returncode = proc.poll()
        if returncode is None:
            try:
                returncode = proc.wait(timeout=5)
            except Exception:
                kill_process_tree(proc, reason="demucs_wait_timeout")
                returncode = proc.poll() if proc.poll() is not None else -1
    finally:
        stop_heartbeat.set()
        t_err.join(timeout=2.0)
        t_out.join(timeout=2.0)

    err = ("".join(stderr_chunks) or "".join(stdout_chunks) or "").strip()
    return int(returncode if returncode is not None else -1), err, cancelled


def _probe_wav_duration_s(path: str | Path) -> float:
    try:
        import wave

        with wave.open(str(path), "rb") as wf:
            frames = int(wf.getnframes() or 0)
            rate = int(wf.getframerate() or 0)
            if frames > 0 and rate > 0:
                return float(frames) / float(rate)
    except Exception:
        pass
    try:
        from ..asr.whisper_fw import _probe_duration_s

        return float(_probe_duration_s(str(path)) or 0.0)
    except Exception:
        return 0.0


def _clamp_demucs_auto_split_minutes(raw: Any) -> int:
    try:
        n = int(round(float(raw)))
    except (TypeError, ValueError):
        return 120
    return max(0, min(720, n))


def _clamp_demucs_chunk_minutes(raw: Any) -> int:
    try:
        n = int(round(float(raw)))
    except (TypeError, ValueError):
        return 60
    return max(10, min(240, n))


def _plan_demucs_outer_chunks(
    duration_s: float,
    *,
    auto_split_minutes: int,
    chunk_minutes: int,
    overlap_s: float = 4.0,
) -> list[tuple[float, float]]:
    """
    Return [(start_s, end_s), ...] for outer Demucs chunks.

    Empty list means "run once on the full file".
    """
    dur = float(duration_s or 0.0)
    if dur <= 1.0:
        return []
    auto_min = _clamp_demucs_auto_split_minutes(auto_split_minutes)
    if auto_min <= 0:
        return []
    if dur < float(auto_min) * 60.0:
        return []
    stride = float(_clamp_demucs_chunk_minutes(chunk_minutes)) * 60.0
    if stride <= 30.0:
        stride = 600.0
    # Need at least ~1.15 chunks worth of media; otherwise keep single pass.
    if dur <= stride * 1.05:
        return []
    ov = max(0.5, min(12.0, float(overlap_s)))
    spans: list[tuple[float, float]] = []
    start = 0.0
    while start < dur - 0.25:
        end = min(dur, start + stride + (ov if start + stride < dur - 0.25 else 0.0))
        if end <= start + 0.25:
            break
        spans.append((start, end))
        next_start = start + stride
        if next_start >= dur - 0.25:
            break
        # Guard against tiny leftover tails: merge into previous by extending.
        if dur - next_start < max(30.0, stride * 0.15) and spans:
            spans[-1] = (spans[-1][0], dur)
            break
        start = next_start
    return spans if len(spans) >= 2 else []


def _read_wav_f32_mono(path: Path) -> tuple[int, Any]:
    import numpy as np
    import wave

    with wave.open(str(path), "rb") as wf:
        sr = int(wf.getframerate() or 44100)
        ch = int(wf.getnchannels() or 1)
        sw = int(wf.getsampwidth() or 2)
        n = int(wf.getnframes() or 0)
        raw = wf.readframes(n)
    if sw == 2:
        data = np.frombuffer(raw, dtype=np.int16).astype(np.float32) / 32768.0
    elif sw == 4:
        data = np.frombuffer(raw, dtype=np.int32).astype(np.float32) / 2147483648.0
    else:
        data = np.frombuffer(raw, dtype=np.uint8).astype(np.float32)
        data = (data - 128.0) / 128.0
    if ch > 1:
        data = data.reshape(-1, ch).mean(axis=1)
    return sr, data


def _write_wav_f32_mono(path: Path, sr: int, audio: Any) -> None:
    import numpy as np
    import wave

    clipped = np.clip(np.asarray(audio, dtype=np.float32), -1.0, 1.0)
    pcm = (clipped * 32767.0).astype(np.int16)
    path.parent.mkdir(parents=True, exist_ok=True)
    with wave.open(str(path), "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(int(sr))
        wf.writeframes(pcm.tobytes())


def _ola_merge_vocals(
    parts: list[tuple[float, Path]],
    *,
    duration_s: float,
    overlap_s: float,
    out_path: Path,
) -> None:
    """Overlap-add mono WAVs placed at media timeline starts."""
    import numpy as np

    if not parts:
        raise RuntimeError("Demucs chunk merge: no vocal parts")
    if len(parts) == 1:
        shutil.copy2(parts[0][1], out_path)
        return

    sr0, first = _read_wav_f32_mono(parts[0][1])
    total_n = max(len(first), int(round(float(duration_s) * float(sr0))) + 8)
    acc = np.zeros(total_n, dtype=np.float64)
    wsum = np.zeros(total_n, dtype=np.float64)
    ov_n = max(1, int(round(float(overlap_s) * float(sr0))))

    for idx, (start_s, path) in enumerate(parts):
        sr, audio = _read_wav_f32_mono(path)
        if sr != sr0:
            # Resample is rare (all chunks from same demucs); fall back to truncate/pad rate mismatch.
            _log.warning("demucs chunk sr mismatch %s vs %s; using as-is", sr, sr0)
        n = int(audio.shape[0])
        if n <= 0:
            continue
        win = np.ones(n, dtype=np.float64)
        if idx > 0 and n > 1:
            fade = min(ov_n, n)
            win[:fade] = np.linspace(0.0, 1.0, fade, endpoint=True)
        if idx < len(parts) - 1 and n > 1:
            fade = min(ov_n, n)
            win[-fade:] = np.linspace(1.0, 0.0, fade, endpoint=True)
        i0 = max(0, int(round(float(start_s) * float(sr0))))
        i1 = i0 + n
        if i1 > total_n:
            extra = i1 - total_n
            acc = np.pad(acc, (0, extra))
            wsum = np.pad(wsum, (0, extra))
            total_n = i1
        acc[i0:i1] += audio.astype(np.float64) * win
        wsum[i0:i1] += win

    mask = wsum > 1e-8
    merged = np.zeros(total_n, dtype=np.float32)
    merged[mask] = (acc[mask] / wsum[mask]).astype(np.float32)
    target_n = max(1, int(round(float(duration_s) * float(sr0))))
    if merged.shape[0] < target_n:
        merged = np.pad(merged, (0, target_n - merged.shape[0]))
    elif merged.shape[0] > target_n:
        merged = merged[:target_n]
    _write_wav_f32_mono(out_path, sr0, merged)


def _demucs_encode_vocals_16k(ffmpeg: str, raw_vocals: Path, out: Path) -> None:
    _run_ffmpeg(
        [
            ffmpeg,
            "-y",
            "-i",
            str(raw_vocals),
            "-ac",
            "1",
            "-ar",
            "16000",
            "-f",
            "wav",
            str(out),
        ]
    )


def _run_demucs_file_with_retries(
    demucs_input: str,
    *,
    demucs_out: Path,
    demucs_device: str,
    device_label: str,
    segment: int | None,
    on_progress: ProgressCb | None,
    should_cancel: Callable[[], bool] | None,
    register_subprocess: Callable[[Any], None] | None,
    started: float,
    progress_detail_prefix: str = "",
) -> Path:
    """Run Demucs CLI on one file; return path to vocals.wav stem."""
    import sys

    def _build_cmd(seg: int | None) -> list[str]:
        parts = [
            sys.executable,
            "-m",
            "demucs",
            "-n",
            "htdemucs",
            "--two-stems",
            "vocals",
            "-d",
            demucs_device,
            "-o",
            str(demucs_out),
        ]
        if seg is not None and seg > 0:
            parts.extend(["--segment", str(int(_clamp_demucs_segment(seg) or seg))])
        parts.append(demucs_input)
        return parts

    attempt_segments: list[int | None] = [segment]
    if demucs_device == "cuda":
        for fallback in (4,):
            if segment is None or fallback < int(segment):
                attempt_segments.append(fallback)

    last_rc = -1
    last_err = ""
    used_segment: int | None = segment
    for attempt_i, seg in enumerate(attempt_segments):
        if should_cancel and should_cancel():
            raise RuntimeError("cancelled")
        if attempt_i > 0:
            try:
                if demucs_out.is_dir():
                    shutil.rmtree(demucs_out, ignore_errors=True)
                demucs_out.mkdir(parents=True, exist_ok=True)
            except Exception:
                pass
            _prepare_vram_for_demucs()
            if on_progress:
                prefix = f"{progress_detail_prefix} · " if progress_detail_prefix else ""
                on_progress(
                    {
                        "stage": "separate",
                        "percent": 11,
                        "detail": f"{prefix}显存不足，改用更短分段（{seg}s）重试…",
                    }
                )
            _log.warning(
                "demucs OOM retry attempt=%s segment=%s device=%s",
                attempt_i + 1,
                seg,
                demucs_device,
            )

        used_segment = seg
        rc, err, cancelled = _run_demucs_cli(
            _build_cmd(seg),
            device_label=device_label,
            on_progress=on_progress,
            should_cancel=should_cancel,
            register_subprocess=register_subprocess,
            started=started,
        )
        if cancelled or (should_cancel and should_cancel()):
            raise RuntimeError("cancelled")
        if rc == 0:
            last_rc = 0
            last_err = ""
            break
        last_rc = rc
        last_err = err
        try:
            _log.warning(
                "demucs failed rc=%s segment=%s root=%s stderr_tail=\n%s",
                rc,
                seg,
                _extract_demucs_root_cause(err),
                (err[-2500:] if err else "(empty)"),
            )
        except Exception:
            pass
        if not _demucs_err_worth_segment_retry(err):
            break
        if attempt_i >= len(attempt_segments) - 1:
            break

    if last_rc != 0:
        raise RuntimeError(
            _format_demucs_failure(last_rc, last_err, segment=used_segment)
        )

    raw_vocals = _find_demucs_vocals(demucs_out, Path(demucs_input).stem)
    if not raw_vocals:
        raise RuntimeError("Demucs finished but vocals.wav was not found")
    return Path(raw_vocals)


def separate_vocals(
    media_path: str,
    *,
    device: str = "auto",
    out_dir: Path | None = None,
    on_progress: ProgressCb | None = None,
    should_cancel: Callable[[], bool] | None = None,
    register_subprocess: Callable[[Any], None] | None = None,
    auto_split_minutes: int = 120,
    chunk_minutes: int = 60,
) -> str:
    """
    Advanced vocal separation via Demucs CLI (`python -m demucs`).
    Returns path to mono 16 kHz vocals WAV.

    Long media (≥ ``auto_split_minutes``) is split into outer chunks of
    ``chunk_minutes`` with a short overlap, then overlap-added. This caps host
    RAM which otherwise scales with full-track length. Inner ``--segment`` is
    unchanged (VRAM).
    """
    import time

    if not _demucs_available():
        raise RuntimeError(
            "影视音频增强需要 Demucs。请在设置中「下载 Demucs」，或 pip install 'transub-engine[audio-separate]'"
        )

    _prepare_vram_for_demucs()

    work = Path(out_dir) if out_dir else Path(tempfile.mkdtemp(prefix="transub_sep_"))
    work.mkdir(parents=True, exist_ok=True)
    demucs_out = work / "demucs"
    demucs_out.mkdir(parents=True, exist_ok=True)
    if on_progress:
        on_progress({"stage": "separate", "percent": 8, "detail": "人声分离（Demucs）…"})

    # Extract/resample to wav first — Demucs on raw containers is much slower.
    demucs_input = str(media_path)
    ffmpeg = resolve_ffmpeg()
    if ffmpeg:
        extracted = work / "source_44100.wav"
        try:
            _run_ffmpeg(
                [
                    ffmpeg,
                    "-y",
                    "-i",
                    str(media_path),
                    "-vn",
                    "-af",
                    _AF_TIMELINE_STABLE,
                    "-ac",
                    "2",
                    "-ar",
                    "44100",
                    "-f",
                    "wav",
                    str(extracted),
                ]
            )
            if extracted.is_file() and extracted.stat().st_size > 44:
                demucs_input = str(extracted)
                if on_progress:
                    on_progress({"stage": "separate", "percent": 10, "detail": "已提取音轨，开始分离…"})
        except Exception as err:
            _log.warning("pre-extract for Demucs failed, using original media: %s", err)

    if should_cancel and should_cancel():
        raise RuntimeError("cancelled")

    demucs_device, device_label = _resolve_demucs_device(device)
    segment = _clamp_demucs_segment(_pick_demucs_segment(demucs_device))
    started = time.time()
    auto_min = _clamp_demucs_auto_split_minutes(auto_split_minutes)
    chunk_min = _clamp_demucs_chunk_minutes(chunk_minutes)
    overlap_s = 4.0
    duration_s = _probe_wav_duration_s(demucs_input)
    spans = _plan_demucs_outer_chunks(
        duration_s,
        auto_split_minutes=auto_min,
        chunk_minutes=chunk_min,
        overlap_s=overlap_s,
    )

    def _finish_16k(raw_vocals: Path) -> str:
        if not ffmpeg:
            return str(raw_vocals.resolve())
        out = work / "vocals.wav"
        if on_progress:
            on_progress({"stage": "separate", "percent": 17, "detail": "人声轨道转码中…"})
        _demucs_encode_vocals_16k(ffmpeg, raw_vocals, out)
        elapsed = int(time.time() - started)
        _log.info(
            "stage demucs: separate %.2fs | device=%s | out=%s",
            float(elapsed),
            device_label,
            out.name,
        )
        if on_progress:
            on_progress(
                {
                    "stage": "separate",
                    "percent": 18,
                    "detail": f"人声分离完成（{device_label}，用时 {elapsed // 60}分{elapsed % 60:02d}秒）",
                }
            )
        return str(out.resolve())

    if not spans:
        seg_hint = f"，分段 {segment}s" if segment else ""
        if on_progress:
            on_progress(
                {
                    "stage": "separate",
                    "percent": 11,
                    "detail": (
                        f"Demucs 分离中（{device_label}{seg_hint}）…"
                        f"首次会下载模型，片长越长越慢"
                    ),
                }
            )
        raw_vocals = _run_demucs_file_with_retries(
            demucs_input,
            demucs_out=demucs_out,
            demucs_device=demucs_device,
            device_label=device_label,
            segment=segment,
            on_progress=on_progress,
            should_cancel=should_cancel,
            register_subprocess=register_subprocess,
            started=started,
        )
        return _finish_16k(raw_vocals)

    if not ffmpeg:
        raise RuntimeError("长片 Demucs 切分需要 ffmpeg")

    n_chunks = len(spans)
    _log.info(
        "demucs outer-chunk: duration=%.0fs auto≥%smin chunk=%smin parts=%s",
        duration_s,
        auto_min,
        chunk_min,
        n_chunks,
    )
    if on_progress:
        on_progress(
            {
                "stage": "separate",
                "percent": 11,
                "detail": (
                    f"Demucs 长片切分（{n_chunks} 块 · 每块约 {chunk_min} 分 · {device_label}）…"
                ),
            }
        )

    chunks_dir = work / "chunks"
    chunks_dir.mkdir(parents=True, exist_ok=True)
    vocal_parts: list[tuple[float, Path]] = []
    for i, (start_s, end_s) in enumerate(spans):
        if should_cancel and should_cancel():
            raise RuntimeError("cancelled")
        chunk_wav = chunks_dir / f"in_{i:03d}.wav"
        chunk_out = chunks_dir / f"demucs_{i:03d}"
        chunk_out.mkdir(parents=True, exist_ok=True)
        dur = max(0.25, float(end_s) - float(start_s))
        pct = 11 + int(6 * i / max(1, n_chunks))
        if on_progress:
            on_progress(
                {
                    "stage": "separate",
                    "percent": min(16, pct),
                    "detail": (
                        f"Demucs 块 {i + 1}/{n_chunks}"
                        f"（{start_s / 60:.0f}–{end_s / 60:.0f} 分 · {device_label}）…"
                    ),
                }
            )
        _run_ffmpeg(
            [
                ffmpeg,
                "-y",
                "-ss",
                f"{start_s:.3f}",
                "-t",
                f"{dur:.3f}",
                "-i",
                demucs_input,
                "-af",
                _AF_TIMELINE_STABLE,
                "-ac",
                "2",
                "-ar",
                "44100",
                "-f",
                "wav",
                str(chunk_wav),
            ]
        )

        raw = _run_demucs_file_with_retries(
            str(chunk_wav),
            demucs_out=chunk_out,
            demucs_device=demucs_device,
            device_label=device_label,
            segment=segment,
            on_progress=on_progress,
            should_cancel=should_cancel,
            register_subprocess=register_subprocess,
            started=started,
            progress_detail_prefix=f"块 {i + 1}/{n_chunks}",
        )
        # Normalize to PCM16 mono before OLA — Demucs often writes float WAV.
        part_vocals = chunks_dir / f"vocals_{i:03d}.wav"
        _run_ffmpeg(
            [
                ffmpeg,
                "-y",
                "-i",
                str(raw),
                "-ac",
                "1",
                "-ar",
                "44100",
                "-sample_fmt",
                "s16",
                "-f",
                "wav",
                str(part_vocals),
            ]
        )
        vocal_parts.append((float(start_s), part_vocals))
        # Free per-chunk demucs tree + input ASAP (host RAM / disk).
        try:
            chunk_wav.unlink(missing_ok=True)  # type: ignore[call-arg]
        except TypeError:
            try:
                chunk_wav.unlink()
            except Exception:
                pass
        except Exception:
            pass
        try:
            shutil.rmtree(chunk_out, ignore_errors=True)
        except Exception:
            pass

    merged_raw = work / "vocals_merged_44100.wav"
    if on_progress:
        on_progress({"stage": "separate", "percent": 16, "detail": "拼接人声块…"})
    _ola_merge_vocals(
        vocal_parts,
        duration_s=duration_s if duration_s > 0 else float(spans[-1][1]),
        overlap_s=overlap_s,
        out_path=merged_raw,
    )
    return _finish_16k(merged_raw)


def trim_media_window(
    media_path: str,
    *,
    start_sec: float = 0.0,
    end_sec: float | None = None,
    duration_sec: float | None = None,
    out_dir: Path | None = None,
) -> str:
    """
    Extract an audio window for ASR testing / partial jobs.

    Returns path to a temporary 16 kHz mono WAV. Cue times from ASR are
    relative to this clip; callers should add ``start_sec`` back.
    """
    ffmpeg = resolve_ffmpeg()
    if not ffmpeg:
        raise RuntimeError("ffmpeg not found; cannot trim media window")

    start = max(0.0, float(start_sec or 0.0))
    dur: float | None = None
    if duration_sec is not None and float(duration_sec) > 0:
        dur = float(duration_sec)
    elif end_sec is not None and float(end_sec) > start:
        dur = float(end_sec) - start
    if dur is not None and dur <= 0:
        raise ValueError("trim window duration must be > 0")

    src = Path(media_path)
    if not src.is_file():
        raise RuntimeError(
            f"ffmpeg 输入不存在（可能被临时目录清理）: {media_path}"
        )
    work = Path(out_dir) if out_dir else Path(tempfile.mkdtemp(prefix="transub_trim_"))
    work.mkdir(parents=True, exist_ok=True)
    out = work / f"{src.stem}.trim.wav"
    cmd = [ffmpeg, "-hide_banner", "-y", "-ss", f"{start:.3f}"]
    if dur is not None:
        cmd += ["-t", f"{dur:.3f}"]
    cmd += [
        "-i",
        str(src),
        "-vn",
        "-af",
        _AF_TIMELINE_STABLE,
        "-ac",
        "1",
        "-ar",
        "16000",
        "-c:a",
        "pcm_s16le",
        str(out),
    ]
    _run_ffmpeg(cmd)
    if not out.is_file() or out.stat().st_size < 64:
        raise RuntimeError(f"trim produced empty audio: {out}")
    return str(out)


def preprocess_media(
    media_path: str,
    audio_opts: dict[str, Any] | None,
    *,
    device: str = "auto",
    on_progress: ProgressCb | None = None,
    should_cancel: Callable[[], bool] | None = None,
    register_subprocess: Callable[[Any], None] | None = None,
) -> tuple[str, list[str], dict[str, Any]]:
    """
    Apply timeline stabilize / optional denoise / vocal separation / trim.

    By default extracts a 16 kHz mono WAV with ``aresample=async=1`` so hidden
    audio-track holes become silence (keeps subtitle times aligned with video).
    Integrity findings are stored in ``meta["audioIntegrity"]``.
    Pass ``stabilizeTimeline=false`` to skip.

    Returns ``(path_for_asr, temp_paths_to_cleanup, meta)``.

    When ``enhanceForVadOnly`` is set with vocal separation, Demucs vocals are
    stored in ``meta["vadMedia"]`` for VAD / island timing only; ASR keeps the
    pre-separation path (trimmed / denoised original).

    When Demucs replaces the ASR path (full film enhance), ``meta["timingMedia"]``
    keeps the pre-separation mix so cue paint can use measured mix PCM ends
    while recognition still hears vocals.
    """
    opts = audio_opts if isinstance(audio_opts, dict) else {}
    current = str(media_path)
    temps: list[str] = []
    work = Path(tempfile.mkdtemp(prefix="transub_audio_"))
    meta: dict[str, Any] = {}

    try:
        def _audio_float(*keys: str, default: float | None = None) -> float | None:
            for key in keys:
                if key in opts and opts[key] is not None and str(opts[key]).strip() != "":
                    try:
                        return float(opts[key])
                    except (TypeError, ValueError):
                        continue
            return default

        start_sec = float(_audio_float("startSec", "trimStartSec", "start_sec", default=0.0) or 0.0)
        end_sec = _audio_float("endSec", "trimEndSec", "end_sec")
        duration_sec = _audio_float("durationSec", "trimDurationSec", "duration_sec")
        need_trim = start_sec > 0 or end_sec is not None or duration_sec is not None

        if need_trim:
            if on_progress:
                detail = f"截取 {start_sec:.0f}s"
                if duration_sec:
                    detail += f" · {duration_sec:.0f}s"
                elif end_sec is not None:
                    detail += f"–{end_sec:.0f}s"
                on_progress({"stage": "trim", "percent": 3, "detail": detail})
            trimmed = trim_media_window(
                current,
                start_sec=start_sec,
                end_sec=end_sec,
                duration_sec=duration_sec,
                out_dir=work / "trim",
            )
            temps.append(trimmed)
            current = trimmed

        # Timeline stabilize + integrity: fill hidden audio holes with silence so
        # ASR timestamps stay aligned with video (damaged web rips).
        want_stabilize = opts.get("stabilizeTimeline")
        if want_stabilize is None:
            want_stabilize = opts.get("stabilize_timeline")
        do_stabilize = True if want_stabilize is None else bool(want_stabilize)

        integrity_meta = None
        if do_stabilize and resolve_ffmpeg():
            from .audio_integrity import IntegrityProbe, console_message

            if on_progress:
                on_progress(
                    {
                        "stage": "preprocess",
                        "percent": 3,
                        "detail": "对齐音轨时间轴（填补坏轨空隙）…",
                    }
                )
            probe = IntegrityProbe(resolve_ffprobe() or None, current)
            try:
                stabilized, ff_stderr, extracted_s = stabilize_media_timeline(
                    current,
                    out_dir=work / "stable",
                )
                temps.append(stabilized)
                current = stabilized
                report = probe.finish(extracted_s, ff_stderr)
            except Exception as err:
                report = probe.finish(None, "")
                _log.warning("timeline stabilize failed, continuing with source: %s", err)
                if on_progress:
                    on_progress(
                        {
                            "stage": "preprocess",
                            "percent": 3,
                            "detail": f"音轨对齐失败，沿用原文件：{err}",
                        }
                    )
            else:
                integrity_meta = report.to_dict()
                msg = console_message(report, Path(media_path).name, repaired=True)
                if report.suspect:
                    _log.warning("%s", msg)
                    if on_progress:
                        on_progress(
                            {
                                "stage": "preprocess",
                                "percent": 4,
                                "detail": msg[:220],
                            }
                        )
                else:
                    _log.info("%s", msg)
            if integrity_meta is not None:
                meta["audioIntegrity"] = integrity_meta
            meta["timelineStabilized"] = bool(temps)

        separate = bool(opts.get("separate") or opts.get("vocalSeparate") or opts.get("filmAudioEnhance"))
        enhance_for_vad = bool(
            opts.get("enhanceForVadOnly")
            or opts.get("enhance_for_vad")
            or opts.get("enhanceForVad")
        )
        denoise = str(opts.get("denoise") or "").strip().lower()
        if denoise in ("1", "true", "yes", "on"):
            denoise = "light"

        if separate:
            if on_progress:
                detail = (
                    "影视人声分离（仅供 VAD）…"
                    if enhance_for_vad
                    else "影视人声分离…"
                )
                on_progress({"stage": "separate", "percent": 5, "detail": detail})
            vocals = separate_vocals(
                current,
                device=device,
                out_dir=work / "sep",
                on_progress=on_progress,
                should_cancel=should_cancel,
                register_subprocess=register_subprocess,
                auto_split_minutes=_clamp_demucs_auto_split_minutes(
                    opts.get("filmDemucsAutoSplitMinutes")
                    if opts.get("filmDemucsAutoSplitMinutes") is not None
                    else opts.get("demucsAutoSplitMinutes", 120)
                ),
                chunk_minutes=_clamp_demucs_chunk_minutes(
                    opts.get("filmDemucsChunkMinutes")
                    if opts.get("filmDemucsChunkMinutes") is not None
                    else opts.get("demucsChunkMinutes", 60)
                ),
            )
            temps.append(vocals)
            if enhance_for_vad:
                # VAD / island timing on vocals; ASR stays on pre-Demucs audio.
                meta["vadMedia"] = vocals
                meta["enhanceForVadOnly"] = True
                # Do not stack light denoise onto the ASR path after Demucs.
            else:
                # ASR hears vocals; keep mix path for cue paint (playback clock).
                meta["timingMedia"] = current
                current = vocals
                # After separation, light denoise is usually unnecessary; still allow explicit.
                if denoise == "light":
                    if on_progress:
                        on_progress({"stage": "denoise", "percent": 16, "detail": "轻度降噪…"})
                    denoised = light_denoise(current, out_dir=work / "denoise")
                    temps.append(denoised)
                    current = denoised
        elif denoise == "light":
            if on_progress:
                on_progress({"stage": "denoise", "percent": 5, "detail": "轻度降噪…"})
            denoised = light_denoise(current, out_dir=work / "denoise")
            temps.append(denoised)
            current = denoised
        elif not temps and current == str(media_path) and not need_trim:
            # Nothing produced (stabilize disabled / ffmpeg missing) — drop empty work dir
            try:
                shutil.rmtree(work, ignore_errors=True)
            except Exception:
                pass
            return current, [], meta

        return current, temps + [str(work)], meta
    except Exception:
        try:
            shutil.rmtree(work, ignore_errors=True)
        except Exception:
            pass
        raise


def cleanup_temps(paths: list[str] | None) -> None:
    for p in paths or []:
        try:
            path = Path(p)
            if path.is_dir():
                shutil.rmtree(path, ignore_errors=True)
            elif path.is_file():
                path.unlink(missing_ok=True)  # type: ignore[call-arg]
        except TypeError:
            try:
                Path(p).unlink()
            except Exception:
                pass
        except Exception as err:
            _log.debug("cleanup failed for %s: %s", p, err)


# Known mkdtemp / mkstemp prefixes created by ASR / audio paths.
_JOB_TEMP_PREFIXES: tuple[str, ...] = (
    "transub_audio_",
    "transub_denoise_",
    "transub_sep_",
    "transub_trim_",
    "transub_awin_",
    "aw_ten_isle_",
    "parakeet_",
    "qwen3_asr_",
    "qwen3_ten_",
    "cohere_asr_",
    "firered_asr2_",
    "reazon_k2_",
    "transub_sv_job_",
    "transub_sv_chunk_",
    "transub_sv_",
    "transub_av_",
    "transub_retry_",
)


def _rm_temp_entry(path: Path) -> bool:
    try:
        if path.is_dir():
            shutil.rmtree(path, ignore_errors=True)
            return not path.exists()
        if path.is_file() or path.is_symlink():
            path.unlink(missing_ok=True)  # type: ignore[call-arg]
            return not path.exists()
    except TypeError:
        try:
            if path.is_file():
                path.unlink()
                return True
        except Exception:
            return False
    except Exception as err:
        _log.debug("sweep failed for %s: %s", path, err)
    return False


def sweep_job_temps(*, min_age_s: float = 0.0) -> dict[str, Any]:
    """
    Remove leftover job scratch under tempfile.gettempdir().

    When the desktop shell sets TRANSUB_ENGINE_TEMP (dedicated engine-work dir),
    clear that entire root so third-party random temps are also reclaimed.
    Otherwise only delete known Transub / ASR prefixes.
    """
    import time

    removed = 0
    mode = "prefixes"
    root = Path(tempfile.gettempdir())
    marker = str(os.environ.get("TRANSUB_ENGINE_TEMP") or "").strip()
    try:
        if marker:
            marked = Path(marker).resolve()
            if marked.is_dir() and marked == root.resolve():
                mode = "engine_temp_root"
                for child in list(marked.iterdir()):
                    if _rm_temp_entry(child):
                        removed += 1
                return {"removed": removed, "mode": mode, "root": str(root)}
    except Exception as err:
        _log.debug("engine temp root sweep skipped: %s", err)

    if not root.is_dir():
        return {"removed": 0, "mode": mode, "root": str(root)}

    now = time.time()
    try:
        children = list(root.iterdir())
    except Exception as err:
        _log.debug("temp listing failed: %s", err)
        return {"removed": 0, "mode": mode, "root": str(root), "error": str(err)}

    for child in children:
        name = str(child.name or "")
        if not any(name.startswith(p) for p in _JOB_TEMP_PREFIXES):
            continue
        if min_age_s > 0:
            try:
                age = now - float(child.stat().st_mtime)
                if age < float(min_age_s):
                    continue
            except Exception:
                continue
        if _rm_temp_entry(child):
            removed += 1
    return {"removed": removed, "mode": mode, "root": str(root)}

